s = open('p2_build.py').read()
s = s.replace("        occ[..., :3] = C.softcap(occ[..., :3], cap_occ, 0.45)\n        gh[..., :3] = C.softcap(gh[..., :3], cap_occ, 0.45)\n", "        occ[..., :3] = hcap(occ[..., :3], cap_occ)\n        gh[..., :3] = hcap(gh[..., :3], cap_occ)\n")
s = s.replace("        lay['spill'][..., :3] = C.softcap(lay['spill'][..., :3], cap_spill, 0.4)\n", "        lay['spill'][..., :3] = hcap(lay['spill'][..., :3], cap_spill)\n")
s = s.replace("def compose(beat,", "def hcap(x, cap):\n    \"\"\"hue-preserving highlight cap: scale each pixel so its max channel never exceeds cap (smooth knee at 0.6 cap).\"\"\"\n    m = x.max(-1, keepdims=True)\n    t = cap * 0.6\n    new = np.where(m > t, t + (cap - t) * (1 - np.exp(-(m - t) / max(cap - t, 1e-6))), m)\n    return x * (new / np.maximum(m, 1e-6))\n\n\ndef compose(beat,", 1)
open('p2_build.py', 'w').write(s)
f = open('p1_final.py').read()
f = f.replace("'impact': dict(cap_occ=1.5, cap_spill=1.2), 'home_hit': dict(cap_occ=1.7, cap_spill=1.4)", "'impact': dict(cap_occ=1.0, cap_spill=0.8), 'home_hit': dict(cap_occ=1.1, cap_spill=0.9)")
open('p1_final.py', 'w').write(f)
print('ok')
